public int findLargestSubstring(List<String> strings) {
    // Initialize a hash map to store the frequencies of each string
    Map<String, Integer> frequencyMap = new HashMap<>();
    for (String string : strings) {
        frequencyMap.put(string, frequencyMap.getOrDefault(string, 0) + 1);
    }

    // Iterate over the strings and find the largest string that is a substring of any other string
    int largestStringLength = 0;
    for (String string : strings) {
        if (string.length() > largestStringLength && frequencyMap.containsKey(new StringBuilder(string).reverse().toString())) {
            largestStringLength = string.length();
        }
    }

    return largestStringLength;
}
