public int maxUniqueSplit(String s) {
    Map<String, Integer> frequencyMap = new HashMap<>();

    for (int i = 0; i < s.length(); i++) {
        String substring = s.substring(i, s.length());
        if (!frequencyMap.containsKey(substring)) {
            frequencyMap.put(substring, 0);
        }

        for (int j = i - 1; j >= 0; j--) {
            String prefix = s.substring(j, i);
            if (prefix.length() > substring.length()) {
                break;
            }

            if (substring.startsWith(prefix)) {
                if (frequencyMap.containsKey(prefix)) {
                    frequencyMap.put(prefix, frequencyMap.get(prefix) + 1);
                } else {
                    frequencyMap.put(prefix, 1);
                }
            }
        }
    }

    int count = 0;
    for (String key : frequencyMap.keySet()) {
        if (frequencyMap.get(key) == 1) {
            count++;
        }
    }

    return count;
