public int countDistinctPrimeFactors(int n) {
    // Create a set to store the distinct prime factors
    Set<Integer> primeFactors = new HashSet<>();

    // Loop through the numbers from 2 to sqrt(n)
    for (int i = 2; i <= Math.sqrt(n); i++) {
        while (n % i == 0) {
            primeFactors.add(i);
            n /= i;
        }
    }

    // If n is not 1, it means that it's a prime factor
    if (n > 1) {
        primeFactors.add(n);
    }

    // Return the size of the set
    return primeFactors.size();
}
